function validarNumero(valor, nome) {
  if (typeof valor !== 'number') throw new TypeError(nome + ' deve ser número');
  if (!Number.isFinite(valor) || valor < 0) throw new RangeError(nome + ' deve ser finito e não negativo');
}

export function cotarEntrega(pedido) {
  const pesoGramas = pedido.pesoGramas;
  const distanciaKm = pedido.distanciaKm;
  validarNumero(pesoGramas, 'pesoGramas');
  validarNumero(distanciaKm, 'distanciaKm');
  const kgExtras = Math.max(0, Math.ceil(pesoGramas / 1000) - 1);
  const kmExtras = Math.max(0, Math.ceil(distanciaKm - 5));
  return 800 + kgExtras * 150 + kmExtras * 40;
}

export function descreverCotacao(centavos) {
  return 'Entrega: R$ ' + (centavos / 100).toFixed(2).replace('.', ',');
}

