export function medias(valores, janela) {
  if (!Number.isInteger(janela) || janela < 1) {
    throw new RangeError('janela deve ser inteiro maior que zero');
  }
  const resultado = [];
  for (let inicio = 0; inicio + janela <= valores.length; inicio++) {
    let soma = 0;
    for (let i = inicio; i < inicio + janela; i++) soma += valores[i];
    resultado.push(soma / janela);
  }
  return resultado;
}

